let currentActiveCategory="all";function renderMenuItems(e,n){n&&(0!==e.length?n.innerHTML=e.map(e=>`\n    <div class="menu-card-item" data-category="${e.category}">\n      ${e.image?`\n        <div class="menu-card-img-wrap">\n          <img class="menu-card-img" src="${e.image}" alt="${e.name}" loading="lazy">\n          ${e.badge?`<span class="badge badge-barn menu-card-badge-overlay">${e.badge}</span>`:""}\n        </div>\n      `:""}\n      <div class="menu-card-top">\n        <h3 class="menu-card-name">${e.name}</h3>\n        <span class="menu-card-price">${e.price}</span>\n      </div>\n      <p class="menu-card-body">${e.description}</p>\n      <div style="margin-top: 14px; display: flex; gap: 8px; flex-wrap: wrap;">\n        <button type="button" class="btn btn-wheat" style="padding: 6px 12px; font-size: 0.82rem; background-color: var(--color-wheat); color: var(--color-ink); border: none;">🔍 View Details</button>\n        <a class="btn btn-barn" href="tel:+16209092090" style="padding: 6px 12px; font-size: 0.82rem;">📞 Call Order</a>\n      </div>\n    </div>\n  `).join(""):n.innerHTML='\n      <div style="grid-column: 1/-1; text-align:center; padding: 40px 20px; color: var(--color-ink-soft);">\n        <p style="font-size: 1.05rem; font-weight: 700; margin-bottom: 8px;">No matching dishes found.</p>\n        <p style="font-size: 0.9rem; margin-bottom: 16px;">Try searching for "steak", "tacos", or "burrito".</p>\n        <button type="button" class="btn btn-primary" onclick="filterMenuCategory(\'all\', document.querySelector(\'.tab-button\'))" style="padding: 8px 18px; font-size: 0.88rem;">Clear Filters & Show All Meals</button>\n      </div>\n    ')}function filterMenuCategory(e,n){currentActiveCategory=e,document.querySelectorAll(".tab-button").forEach(e=>e.classList.remove("active")),n&&n.classList.add("active");const t=document.getElementById("menu-search-input");"all"===e&&t&&n&&n.getAttribute("onclick")&&n.getAttribute("onclick").includes("clear")&&(t.value=""),searchMenuItems(t?t.value:"")}function searchMenuItems(e){const n=document.getElementById("menu-grid-container");if(!n||"undefined"==typeof MENU_DATA)return;const t=(e||"").toLowerCase().trim();renderMenuItems(MENU_DATA.filter(e=>{const n="all"===currentActiveCategory||e.category===currentActiveCategory,a=!t||e.name.toLowerCase().includes(t)||e.description.toLowerCase().includes(t)||e.badge&&e.badge.toLowerCase().includes(t);return n&&a}),n)}document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("menu-search-input");e&&e.addEventListener("input",e=>{searchMenuItems(e.target.value)})});